def card(work):

    def smoothstep(x):
        x = clamp01(x)
        return x * x * (3 - 2 * x)

    def world(n_sections, dive=1.3, conn=0.9):
        spans, pos = ([], 0.0)
        for i in range(n_sections):
            spans.append(('section', i, pos, pos + dive))
            pos += dive
            if i < n_sections - 1:
                spans.append(('connector', i, pos, pos + conn))
                pos += conn
        return (spans, pos)

    def at(spans, scroll, crossfade=0.12):
        for kind, i, a, b in spans:
            if a <= scroll < b:
